#!/usr/bin/env python3
"""Random campaign generator: valid metadata, messy captures and planning."""
import base64
import ipaddress
import plistlib
import random
import struct

import zstandard as zstd


def zid(rng, n=6):
    return ''.join(rng.choice('abcdefghij0123456789_-') for _ in range(n))


def doc_addr(rng):
    v = rng.randrange(int(ipaddress.IPv6Address('2001:db8::')),
                      int(ipaddress.IPv6Address('2001:db8:ffff:ffff:ffff:ffff:ffff:ffff')))
    return str(ipaddress.IPv6Address(v))


def spell(rng, addr):
    """Random IPv6 spelling variants (numeric comparison must ignore these)."""
    ip = ipaddress.IPv6Address(addr)
    form = rng.randrange(4)
    if form == 0:
        return str(ip)
    if form == 1:
        return ip.exploded
    if form == 2:
        return ip.exploded.upper()
    return hex(int(ip))


def csvint(rng, value):
    return '0' * rng.randrange(0, 3) + str(value)


def b64(data):
    return base64.b64encode(data).decode()


def adb_valid(rng):
    cmd = rng.choice([0x4e584e43, 0x48545541])
    arg0 = rng.randrange(0, 2**32)
    arg1 = rng.randrange(0, 2**32)
    if cmd == 0x4e584e43:
        body = ('dev-%d' % rng.randrange(1000)).encode()
    else:
        body = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 8)))
    ck = sum(body) & 0xffffffff
    return struct.pack('<6I', cmd, arg0, arg1, len(body), ck, cmd ^ 0xffffffff) + body


def adb_bad(rng):
    p = bytearray(adb_valid(rng))
    mode = rng.randrange(4)
    if mode == 0:
        p[-1] ^= 0xff            # trailing / length mismatch
        return bytes(p) + b'zz'
    if mode == 1:
        p[16] ^= 0xff            # checksum
        return bytes(p)
    if mode == 2:
        p[20] ^= 0xff            # magic
        return bytes(p)
    return bytes(p[:-2])          # truncation


def sync_valid(rng):
    def frame(key, value, binary):
        d = {'Key': key, 'Request': 'GetValue', 'Value': value}
        body = plistlib.dumps(d, fmt=plistlib.FMT_BINARY if binary else plistlib.FMT_XML)
        return struct.pack('>I', len(body)) + body
    binary = rng.randrange(2) == 0
    return frame('ProductVersion', rng.choice(['1.2.3', '14.0', 'x']), binary) + \
        frame('ProductName', rng.choice(['P,1', 'X']), rng.randrange(2) == 0)


def sync_bad(rng):
    good = sync_valid(rng)
    mode = rng.randrange(5)
    if mode == 0:
        return good + b'junk'
    if mode == 1:
        return good[:-1]
    if mode == 2:
        body = plistlib.dumps({'Key': 'ProductVersion', 'Request': 'GetValue', 'Value': ''},
                              fmt=plistlib.FMT_XML)
        bad = struct.pack('>I', len(body)) + body
        return bad + good[struct.unpack('>I', good[:4])[0] + 4:]
    if mode == 3:
        return struct.pack('>I', 70000) + b'x' * 10
    body = plistlib.dumps({'Key': 'Nope', 'Request': 'GetValue', 'Value': 'v'},
                          fmt=plistlib.FMT_XML)
    bad = struct.pack('>I', len(body)) + body
    return bad + good[struct.unpack('>I', good[:4])[0] + 4:]


def make_rows(rng, manifest_map, leases, services):
    """Generate CSV rows (valid and invalid) with revision churn."""
    rows = []
    lease_ids = [l['id'] for l in leases]
    probes = {}
    for (lid, probe), (target, canary) in manifest_map.items():
        probes.setdefault(lid, []).append((probe, target, canary))

    def icmp_row(ident, rev, published, lid, probe, target, canary, result,
                 resp, op='put', event=None, **kw):
        lease = next(l for l in leases if l['id'] == lid)
        if event is None:
            event = rng.randrange(lease['start'], lease['end'])
        r = ['icmp', ident, str(rev), str(published), op, lid, str(event),
             probe, kw.get('target', spell(rng, str(ipaddress.IPv6Address(target)))),
             resp, result, '', '', '']
        return [str(x) for x in r]

    def app_row(ident, rev, published, lid, sid, event, target, result,
                attempt, payload, op='put', resp='', probe=''):
        return ['app', ident, str(rev), str(published), op, lid, str(event), probe,
                spell(rng, target), resp, result, sid, str(attempt), payload]

    kinds = services
    # scenario scripts
    for lid in lease_ids:
        plist = probes[lid]
        for i in range(rng.randrange(1, 5)):
            probe, target, canary = plist[rng.randrange(len(plist))]
            ident = zid(rng)
            rev = rng.randrange(0, 3)
            pub = rng.randrange(0, 20)
            style = rng.randrange(10)
            if canary and style < 2:
                rows.append(icmp_row(ident, rev, pub, lid, probe, target, canary,
                                     'echo', spell(rng, str(ipaddress.IPv6Address(target)))))
            elif style < 5:
                rows.append(icmp_row(ident, rev, pub, lid, probe, target, canary,
                                     'echo', spell(rng, str(ipaddress.IPv6Address(target)))))
            elif style < 7:
                ext = doc_addr(rng)
                rows.append(icmp_row(ident, rev, pub, lid, probe, target, canary,
                                     rng.choice(['echo', 'error']), spell(rng, ext)))
            elif style < 8:
                rows.append(icmp_row(ident, rev, pub, lid, probe, target, canary,
                                     'error', spell(rng, str(ipaddress.IPv6Address(target)))))
            else:
                rows.append(icmp_row(ident, rev, pub, lid, probe, target, canary,
                                     'timeout', ''))
            # revision churn / tombstones / conflicts on the same identity
            if rng.random() < 0.3:
                probe2, target2, canary2 = plist[rng.randrange(len(plist))]
                style2 = rng.randrange(4)
                if style2 == 0:
                    rows.append(icmp_row(ident, rev + 1, pub + rng.randrange(1, 5),
                                         lid, probe2, target2, canary2,
                                         'echo', spell(rng, str(ipaddress.IPv6Address(target2))),
                                         event=rng.randrange(0, 20)))
                elif style2 == 1:
                    rows.append(['icmp', ident, str(rev + 1), str(pub + 3), 'delete',
                                 '', '', '', '', '', '', '', '', ''])
                elif style2 == 2:
                    # two distinct contents at same new revision -> conflict
                    rows.append(icmp_row(ident, rev + 1, pub + 1, lid, probe2, target2,
                                         canary2, 'timeout', ''))
                    rows.append(icmp_row(ident, rev + 1, pub + 2, lid, probe, target,
                                         canary, 'timeout', ''))
                else:
                    # identical content, different spelling -> collapses
                    rows.append(icmp_row(ident, rev, pub + 2, lid, probe, target, canary,
                                         'timeout', ''))
        # application rows
        for i in range(rng.randrange(0, 4)):
            ident = zid(rng)
            if not kinds:
                continue
            sid = rng.choice(list(kinds))
            kind = kinds[sid]
            target = doc_addr(rng)
            if plist and rng.random() < 0.7:
                target = str(ipaddress.IPv6Address(plist[rng.randrange(len(plist))][1]))
            attempt = rng.randrange(0, 3)
            result = rng.choice(['open', 'closed', 'timeout', 'open'])
            if result == 'open':
                if kind == 'tcp':
                    payload = ''
                elif kind == 'adb':
                    payload = b64(adb_valid(rng) if rng.random() < 0.7 else adb_bad(rng))
                else:
                    payload = b64(sync_valid(rng) if rng.random() < 0.7 else sync_bad(rng))
            else:
                payload = ''
            rows.append(app_row(ident, rng.randrange(0, 3), rng.randrange(0, 20),
                                lid, sid, rng.randrange(0, 20), target, result,
                                attempt, payload))
        # invalid rows sprinkled in
        for i in range(rng.randrange(0, 3)):
            ident = zid(rng)
            rows.append(['icmp', ident, 'x', '1', 'put', lid, '1', '0/i1',
                         doc_addr(rng), '', 'echo', '', '', ''])
            rows.append(['app', ident, '1', '1', 'put', lid, '1', '', doc_addr(rng),
                         '', 'open', 'nosuch', '0', ''])
            rows.append(['icmp', ident + 'Z' * 40, '1', '1', 'delete', '', '', '',
                         '', '', '', '', '', ''])
    rng.shuffle(rows)
    return rows


def rows_to_csv(rows, header=True):
    import io
    buf = io.StringIO(newline='')
    import csv
    w = csv.writer(buf, lineterminator='\n')
    if header:
        w.writerow(['type', 'id', 'revision', 'published', 'op', 'lease', 'event',
                    'probe', 'target', 'responder', 'result', 'service', 'attempt',
                    'payload'])
    for r in rows:
        w.writerow(r)
    return buf.getvalue()


def chunked(rng, data, n=3):
    cuts = sorted(rng.randrange(0, len(data) + 1) for _ in range(n - 1))
    out, prev = [], 0
    for c in cuts + [len(data)]:
        out.append(data[prev:c])
        prev = c
    return [b64(c) for c in out]


